/**
 *
 * @param {*} T 工作时长
 * @param {*} tws 数组，元素是tw，也是数组，含义为[该工作消耗的时长, 该项工作的报酬]
 * @param {*} n 工作数量
 */
function getResult(T, tws, n) {
  tws = [[0, 0], ...tws];
  const dp = new Array(T + 1).fill(0);

  // 01背包问题滚动数组优化
  for (let i = 1; i <= n; i++) {
    const [t, w] = tws[i];
    // 注意背包承重遍历必须倒序，正序的话就变成完全背包了
    for (let j = T; j >= t; j--) {
      dp[j] = Math.max(dp[j], dp[j - t] + w);
    }
  }

  return dp[T];
}

